const getScorePercent = (score, { values, percents }) => {
  const clampedScore = Math.max(0, Math.min(score, 100));
  let totalPercent = 0;
  for (let i = 0; i < values.length - 1; i++) {
    const min2 = values[i];
    const max2 = values[i + 1];
    const percent = percents[i];
    if (clampedScore < max2) {
      const range = max2 - min2;
      const ratioInRange = (clampedScore - min2) / range;
      totalPercent += percent * ratioInRange;
      break;
    } else {
      totalPercent += percent;
    }
  }
  return parseFloat(totalPercent.toFixed(1));
};
