function drawFdiTrendChart(selector, data) {
  const {
    testData
  } = data;
  const xAxisData = testData.map((i) => i.time);
  const seriesData = testData.map((item) => {
    return {
      ...item,
      itemStyle: {
        color: generateImmunityLevelAndColor(item.value)[1]
      },
      label: {
        position: item.value >= 90 ? "bottom" : item.value <= 10 ? "top" : "top"
      }
    };
  });
  const containerHeight = 260;
  const yAxisMax = 100;
  const gridTop = 10;
  const gridHeight = containerHeight - 20;
  const barWidth2 = 10;
  const options = {
    grid: {
      left: 140,
      right: 0,
      top: gridTop + "px",
      bottom: 0,
      containLabel: true
    },
    animation: false,
    xAxis: {
      type: "category",
      axisLine: {
        lineStyle: {
          color: "#F2F2F2"
        }
      },
      axisTick: {
        lineStyle: {
          color: "#D9D9D9"
        }
      },
      axisLabel: {
        color: "#7F7F7F",
        margin: 15,
        interval: 0,
        fontFamily: "Microsoft YaHei"
      },
      data: xAxisData
    },
    yAxis: {
      type: "value",
      min: 0,
      max: yAxisMax,
      axisLine: {
        show: false
      },
      axisTick: {
        show: false
      },
      axisLabel: {
        show: false
      },
      splitLine: {
        show: false
      }
    },
    series: [{
      data: seriesData,
      type: "line",
      smooth: true,
      symbol: "path://M8,0 A8,8 0 1,0 -8,0 A8,8 0 1,0 8,0 Z",
      symbolSize: 12,
      itemStyle: {
        borderColor: "#fff",
        borderWidth: 2
      },
      lineStyle: {
        color: "#ccc",
        type: "dashed"
      },
      label: {
        color: "#606168",
        show: true,
        formatter: function(params) {
          return params.data.valueString;
        }
      }
    }]
  };
  const cutOff = Cutoff.MetaboImmuneSystemAging;
  const getcutOffPercent = (value) => getScorePercent(value, {
    values: [0, ...Cutoff.MetaboImmuneSystemAging, 100],
    percents: SystemLevelPrecent
  });
  const cutOffPercent = cutOff.map((i) => getcutOffPercent(i));
  const segments = [{
    range: [0, cutOffPercent[0]],
    label: `${SystemLevelText[0]}        0-${cutOff[0]}`,
    color: SystemLevelColor[0]
  }, {
    range: [cutOffPercent[0], cutOffPercent[1]],
    label: `${SystemLevelText[1]}  ${cutOff[0]}-${cutOff[1]}`,
    color: SystemLevelColor[1]
  }, {
    range: [cutOffPercent[1], cutOffPercent[2]],
    label: `${SystemLevelText[2]}        ${cutOff[1]}-${cutOff[2]}`,
    color: SystemLevelColor[2]
  }, {
    range: [cutOffPercent[2], cutOffPercent[3]],
    label: `${SystemLevelText[3]}        ${cutOff[2]}-${cutOff[3]}`,
    color: SystemLevelColor[3]
  }, {
    range: [cutOffPercent[3], cutOffPercent[4]],
    label: `${SystemLevelText[4]}    ${cutOff[3]}-${cutOff[4]}`,
    color: SystemLevelColor[4]
  }, {
    range: [cutOffPercent[4], 100],
    label: `${SystemLevelText[5]}  ${cutOff[4]}-100`,
    color: SystemLevelColor[5]
  }];
  const graphic = segments.flatMap((seg) => [{
    type: "rect",
    left: 130,
    top: gridHeight - seg.range[1] / yAxisMax * gridHeight,
    shape: {
      x: 0,
      y: 0,
      width: barWidth2,
      height: (seg.range[1] - seg.range[0]) / yAxisMax * gridHeight,
      r: 5
    },
    style: {
      fill: seg.color
    }
  }, {
    type: "text",
    left: 0,
    top: gridHeight - (seg.range[1] + seg.range[0]) / 2 / yAxisMax * gridHeight,
    style: {
      text: seg.label,
      fill: "#7F7F7F",
      fontSize: 12,
      textAlign: "right",
      fontFamily: "\u5FAE\u8F6F\u96C5\u9ED1"
    }
  }]);
  options.graphic = graphic;
  const chartDom = document.getElementById(selector);
  const myChart = echarts.init(chartDom, null, {
    renderer: "svg"
  });
  myChart.setOption(options);
  return myChart.getDataURL();
}
