function getFdiTrendChartData(m2) {
  const {
    sample: {
      history
    }
  } = window.MetaGuardENLimsData;
  const currentHistoryModel = history[m2].filter((i) => i.result).slice(-4);
  const resultArr = currentHistoryModel.map((item) => {
    let fdiValueString = "";
    let fdiValueNumber = 0;
    if (item.result) {
      const r2 = Decimal.sub(100, new Decimal(item.result.populationRank));
      fdiValueString = toRetain(r2.toNumber(), 1);
      if (r2.lessThan(new Decimal(0.1))) {
        fdiValueString = "0.1";
      }
      fdiValueNumber = parseFloat(fdiValueString);
    }
    return {
      time: item.testingDate,
      value: fdiValueNumber,
      valueString: fdiValueString
    };
  });
  return {
    testData: resultArr
  };
}
